import type { ToolSet } from 'ai'
import {
  transcribe_video,
  extract_concepts,
  render_manim_clips,
  build_hf_composition,
  render_draft_video,
} from './tools'

export function getAvailableTools(
  pipelinePhase: number,
  sessionData: Record<string, unknown>
): ToolSet {
  const pipelineMode = sessionData?.pipelineMode ?? 'auto'
  const awaitingApproval = sessionData?.pipelineStatus === 'awaiting_approval'

  if (pipelinePhase < 2) return {}
  if (pipelinePhase >= 7) return {}
  if (awaitingApproval && pipelineMode === 'ask') return {}

  const tools: ToolSet = {}

  if (pipelinePhase <= 2) tools.transcribe_video = transcribe_video
  if (pipelinePhase <= 3) tools.extract_concepts = extract_concepts
  if (pipelinePhase <= 4) tools.render_manim_clips = render_manim_clips
  if (pipelinePhase <= 5) tools.build_hf_composition = build_hf_composition
  if (pipelinePhase <= 6) tools.render_draft_video = render_draft_video

  return tools
}

export function getPhaseTools(phase: number): ToolSet {
  return getAvailableTools(phase, {})
}

export {
  transcribe_video,
  extract_concepts,
  render_manim_clips,
  build_hf_composition,
  render_draft_video,
}
